package org.marketreview.nativeapp;
import android.content.Context;
import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.*;
import org.json.*;
/** Dedicated research DB; never writes watchlist, trades, BusinessStore or model runs. */
final class StockResearchStore extends SQLiteOpenHelper {
 StockResearchStore(Context context,String name){super(context,name,null,1);}
 public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE research_records(kind TEXT NOT NULL,id TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(kind,id))");}
 public void onUpgrade(SQLiteDatabase db,int old,int next){throw new IllegalStateException("研究库需要明确迁移，未清空");}
 private JSONArray rows(String kind)throws Exception{SQLiteDatabase db=getReadableDatabase();JSONArray rows=new JSONArray();try(Cursor c=db.rawQuery("SELECT id,length(payload),CASE WHEN length(payload)<=24000 THEN payload ELSE NULL END FROM research_records WHERE kind=? ORDER BY rowid",new String[]{kind})){while(c.moveToNext()){if(!c.isNull(2)){rows.put(new JSONObject(c.getString(2)));continue;}long length=c.getLong(1);StockResearchModel.need(length>0&&length<=32*1024*1024,"研究原记录过大或损坏，未截断");StringBuilder payload=new StringBuilder();for(long start=1;start<=length;start+=24000)try(Cursor part=db.rawQuery("SELECT substr(payload,?,24000) FROM research_records WHERE kind=? AND id=?",new String[]{Long.toString(start),kind,c.getString(0)})){StockResearchModel.need(part.moveToFirst()&&!part.isNull(0)&&!part.getString(0).isEmpty(),"研究原文分块不完整");payload.append(part.getString(0));}StockResearchModel.need(payload.codePointCount(0,payload.length())==length,"研究原文长度不一致");rows.put(new JSONObject(payload.toString()));}}return rows;}
 JSONObject backup()throws Exception{SQLiteDatabase db=getReadableDatabase();boolean own=!db.inTransaction();if(own)db.beginTransactionNonExclusive();try{JSONObject out=new JSONObject().put("schema","stock-research/v1").put("notes",rows("notes")).put("snapshots",rows("snapshots"));if(own)db.setTransactionSuccessful();return out;}finally{if(own)db.endTransaction();}}
 JSONObject note(String id)throws Exception{StockResearchModel.identity(id);JSONArray rows=backup().getJSONArray("notes");for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).getString("id")))return rows.getJSONObject(i);return new JSONObject();}
 private void write(SQLiteDatabase db,String kind,JSONObject r,boolean replace)throws Exception{StockResearchModel.validate(kind,r);ContentValues values=new ContentValues();values.put("kind",kind);values.put("id",r.getString("id"));values.put("payload",r.toString());if(replace)StockResearchModel.need(db.insertWithOnConflict("research_records",null,values,SQLiteDatabase.CONFLICT_REPLACE)>=0,"研究保存失败");else db.insertOrThrow("research_records",null,values);}
 JSONObject saveNote(String id,String text,JSONObject expected)throws Exception{StockResearchModel.identity(id);SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{JSONObject current=note(id);StockResearchModel.need(StockResearchModel.canonical(current).equals(StockResearchModel.canonical(expected)),"笔记已变化，请显式放弃或重新加载，未覆盖");JSONObject r=new JSONObject().put("id",id).put("text",text).put("revision",current.optInt("revision")+1);write(db,"notes",r,true);db.setTransactionSuccessful();return r;}finally{db.endTransaction();}}
 void saveSnapshot(JSONObject r)throws Exception{write(getWritableDatabase(),"snapshots",r,false);}
 void merge(JSONObject incoming,JSONObject expected)throws Exception{JSONObject valid=StockResearchModel.decode(incoming.toString());SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{JSONObject current=backup();StockResearchModel.need(StockResearchModel.canonical(current).equals(StockResearchModel.canonical(expected)),"研究库已变化，请重新预览，未写入");JSONObject inserts=StockResearchModel.preview(valid,current).getJSONObject("inserts");for(String k:new String[]{"notes","snapshots"}){JSONArray rows=inserts.getJSONArray(k);for(int i=0;i<rows.length();i++)write(db,k,rows.getJSONObject(i),false);}db.setTransactionSuccessful();}finally{db.endTransaction();}}
}
